        """
        Do not return anything, modify board in-place instead.
        """
        self._solve(board)

    def _solve(self, board: list[list[str]]) -> bool:
        for r in range(9):
            for c in range(9):
                if board[r][c] == '.':
                    for num_char in '123456789':
                        if self._is_valid(board, r, c, num_char):
                            board[r][c] = num_char  # Place the number
                            if self._solve(board):
                                return True  # Solution found
                            board[r][c] = '.'  # Backtrack
                    return False  # No number works for this cell
        return True  # All cells filled, solution found

    def _is_valid(self, board: list[list[str]], row: int, col: int, num_char: str) -> bool:
        # Check row
        for c in range(9):
            if board[row][c] == num_char: return False
        # Check column
        for r in range(9):
            if board[r][col] == num_char: return False
        # Check 3x3 box
        start_row = (row // 3) * 3
        start_col = (col // 3) * 3
        for r_offset in range(3):
            for c_offset in range(3):
                if board[start_row + r_offset][start_col + c_offset] == num_char: return False
        return True

