class Solution {
public:
    // These booleans track if a digit is present in a row, column, or 3x3 box.
    // `rows[i][j]` is true if digit `j` is present in row `i`.
    // `cols[i][j]` is true if digit `j` is present in column `i`.
    // `boxes[i][j]` is true if digit `j` is present in 3x3 box `i`.
    // Note: Array sizes are 10 to use 1-9 directly as indices.
    bool rows[9][10] = {false};
    bool cols[9][10] = {false};
    bool boxes[9][10] = {false};

    void solveSudoku(vector<vector<char>>& board) {
        // Step 1: Initialize constraint tracking arrays based on the initial board.
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                if (board[r][c] != '.') {
                    int num = board[r][c] - '0';
                    int box_idx = (r / 3) * 3 + (c / 3); // Calculate 3x3 box index
                    rows[r][num] = true;
                    cols[c][num] = true;
                    boxes[box_idx][num] = true;
                }
            }
        }
        // Step 2: Start the backtracking process.
        solve(board);
    }

    // Recursive backtracking function
    bool solve(vector<vector<char>>& board) {
        // Iterate through each cell of the board
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                // If the cell is empty ('.')
                if (board[r][c] == '.') {
                    // Try digits from 1 to 9
                    for (int num = 1; num <= 9; ++num) {
                        int box_idx = (r / 3) * 3 + (c / 3);
                        // Check if 'num' is valid for current cell using pre-computed constraints
                        if (!rows[r][num] && !cols[c][num] && !boxes[box_idx][num]) {
                            // Place the number (tentatively)
                            board[r][c] = (char)(num + '0');
                            rows[r][num] = true;
                            cols[c][num] = true;
                            boxes[box_idx][num] = true;

                            // Recursively try to solve the rest of the board
                            if (solve(board)) {
                                return true; // Solution found, propagate true upwards
                            }

                            // Backtrack: If solution not found, undo placement
                            board[r][c] = '.';
                            rows[r][num] = false;
                            cols[c][num] = false;
                            boxes[box_idx][num] = false;
                        }
                    }
                    return false; // No number from 1-9 works for this cell, backtrack further
                }
            }
        }
        return true; // All cells filled, board is solved
    }
};

